import {THEMES,PEOPLE,esc,initials,timeAgo,loadDemo,saveDemo,toggle,addPost,addMessage,addComment,updateProfile,newCircle,cleanText,parseRoute,validateCatalogue,clone} from './core.mjs';
import {ORIGINALS,Player} from './audio.mjs';
import {client,Service,profile as memberProfile} from './backend.mjs';
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog'),audio=document.querySelector('#audio');
const storage={getItem:k=>{try{return localStorage.getItem(k);}catch{return null;}},setItem:(k,v)=>localStorage.setItem(k,v)};
const state={...parseRoute(location.hash),mode:'demo',demo:loadDemo(storage),member:null,service:null,sb:null,epoch:0,loading:false,error:'',feed:'all',people:'all',query:'',music:'original',musicQuery:'',community:[],communityState:'idle',uploads:[],comments:new Set(),drafts:{},liked:[],saved:[],favorites:[],searchResults:[],visitor:null,busy:new Set()};
const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M22 21v-2a4 4 0 0 0-3-3.9M16 3a4 4 0 0 1 0 8',chat:'M21 11a8 8 0 0 1-8 8H7l-5 3 2-6a8 8 0 1 1 17-5ZM7 10h10M7 14h6',music:'M9 18V5l12-2v13M9 8l12-2M9 18a3 2 0 1 1-6 0 3 2 0 0 1 6 0M21 16a3 2 0 1 1-6 0 3 2 0 0 1 6 0',space:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M4 22v-2a8 8 0 0 1 16 0v2',arrow:'M5 12h14M13 6l6 6-6 6',arrowUp:'M6 18 18 6M6 6h12v12',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',save:'M5 3h14v19l-7-5-7 5Z',search:'M21 21l-6-6M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',plus:'M12 4v16M4 12h16',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',image:'M3 3h18v18H3ZM3 16l5-5 4 4 3-3 6 6M16 7h.01',play:'m8 4 12 8-12 8Z',pause:'M8 5v14M16 5v14',next:'m5 5 11 7-11 7ZM20 5v14',previous:'m19 5-11 7 11 7ZM4 5v14',volume:'M11 4 5 9H2v6h3l6 5ZM15 8a5 5 0 0 1 0 8M18 5a9 9 0 0 1 0 14',repeat:'m18 2 4 4-4 4M2 11V8a2 2 0 0 1 2-2h18M6 22l-4-4 4-4M22 13v3a2 2 0 0 1-2 2H2',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1',back:'m14 6-6 6 6 6',leaf:'M20 3C5 3 2 10 6 17s15 2 14-14ZM4 21l11-11',share:'M12 16V2m-5 5 5-5 5 5M5 12H3v9h18v-9h-2',download:'M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5'};
const icon=(name,cls='')=>`<svg class="ico ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.sun}"/></svg>`;
const btn=(label,action,value='',extra='')=>`<button type="button" class="btn ${extra}" data-action="${action}" data-value="${esc(value)}">${label}</button>`;
const avatar=(p,extra='')=>`<span class="avatar ${['peach','lavender','sage','yellow','blue','rose'].includes(p?.color)?p.color:'sage'} ${extra}" aria-hidden="true">${esc(p?.emoji||initials(p?.name))}</span>`;
const brand=(mobile=false)=>`<a class="brand ${mobile?'mobile-brand':''}" href="#${state.page==='welcome'?'welcome':'home'}" aria-label="Sota Kece home"><img src="./icon.svg" alt="" width="36" height="36"><span>Sota Kece<small>a little closer</small></span></a>`;
const me=()=>state.mode==='member'?state.member?.me||{id:state.service?.user?.id,name:'Your space',handle:'',emoji:'☀️',theme:'lagoon'}:state.demo.profile;
const person=id=>id==='you'||id===me().id?me():PEOPLE.find(p=>p.id===id)||state.member?.people?.find(p=>p.id===id)||{id,name:'Member',emoji:'🌺',color:'sage'};
const data=()=>state.mode==='member'?state.member||{}:state.demo;
const posts=()=>data().posts||[];
const circles=()=>data().circles||[];
const saved=()=>state.mode==='demo'?state.demo.saved:state.saved;
const likes=()=>state.mode==='demo'?state.demo.liked:state.liked;
const favorites=()=>state.mode==='demo'?state.demo.favorites:state.favorites;
function persist(){if(state.mode==='demo'&&!saveDemo(storage,state.demo))toast('Your changes work here, but this browser could not save them.');}
let toastTimer;function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function go(page,arg=''){const next='#'+page+(arg?'/'+encodeURIComponent(arg):'');if(location.hash===next)loadPage();else location.hash=next;}
function pageHeader(kicker,title,description='',action=''){return `<header class="page-head"><div><span class="eyebrow">${kicker}</span><h1 tabindex="-1" id="page-title">${title}</h1>${description?`<p>${description}</p>`:''}</div>${action||`<span class="date">${new Intl.DateTimeFormat('en',{weekday:'long',month:'short',day:'numeric'}).format(new Date())}</span>`}</header>`;}
function empty(title,text,action=''){return `<section class="empty">${icon('leaf')}<h2>${esc(title)}</h2><p>${esc(text)}</p>${action}</section>`;}
function art(kind){return `<div class="post-art ${kind}" role="img" aria-label="${kind==='island'?'Original illustration of a quiet island sunset':kind==='craft'?'Original paper-flower illustration':'Original illustration of a vinyl record'}">${kind==='craft'?'<span class="craft-flower"></span>':kind==='music'?'<span class="vinyl"></span>':''}</div>`;}
function album(track,small=false){return `<span class="album-art ${track.art||'lagoon'} ${small?'small':''}" aria-hidden="true"></span>`;}
const navItems=[['home','Home','home'],['people','People','people'],['talanoa','Talanoa','chat'],['music','Music','music'],['space','My space','space']];
function shell(content){const p=me();return `<aside class="rail">${brand()}<span class="eyebrow">Your little corner</span><nav class="main-nav" aria-label="Main navigation">${navItems.map(([key,label,ico])=>`<a href="#${key}" ${state.page===key?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${key==='talanoa'?'<i class="nav-dot" aria-hidden="true"></i>':''}</a>`).join('')}</nav><div class="rail-foot"><div class="mini-mark">✳</div><p>Far apart.<br>Still together.</p><a class="rail-profile" href="#space">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${state.mode==='demo'?'Your sample space':'@'+esc(p.handle)}</small></span></a></div></aside><div class="app-body"><header class="topbar"><span class="crumb">A little closer to the people who matter.</span>${brand(true)}<div class="tools"><span class="mode-badge"><i class="dot"></i><b>${state.mode==='demo'?'Sample community':'Your community'}</b></span>${state.mode==='demo'?btn('Sign in','auth','','small auth'):''}<button class="icon-btn" data-action="activity" aria-label="View activity">${icon('bell')}</button><a href="#settings" class="icon-btn settings" aria-label="Settings">${icon('settings')}</a></div></header><main id="main" class="main">${state.mode==='demo'?'<div class="sample-bar"><span>Preview with fictional people. <span class="extra">Explore freely — </span>changes stay on this device.</span><button data-action="about-demo">About this preview</button></div>':''}${content}</main></div>`;}
function welcome(){return `<header class="welcome-header">${brand()}<nav aria-label="Explore"><a href="#people">People</a><a href="#talanoa">Talanoa</a><a href="#music">Music</a><a href="#space">Your space</a></nav>${btn('Sign in '+icon('arrowUp'),'auth','','small')}</header><main id="main" class="welcome"><section class="landing-hero"><div class="landing-copy"><span class="eyebrow">Fiji roots. Open hearts. Everywhere.</span><h1>Your people.<br>Your rhythm.<br><em>Your place.</em></h1><p>Some connections feel like coming home. A space for good conversations, shared songs and the little things that make you, you.</p><div class="row wrap"><a class="btn primary" href="#home">Come on in ${icon('arrow')}</a>${btn('Make it yours','auth-up','','flat')}</div><p class="quiet-note">Take a look around the sample community.<br>No account needed. Just a little curiosity.</p></div><div class="hero-scene"><img class="hero-art" src="./island.svg" width="1000" height="800" alt="An original illustration of an island, palms and a warm sunset over the sea"><span class="scene-caption">A LITTLE CLOSER TO HOME</span><span class="sunburst" aria-hidden="true">✳</span><div class="float-note"><div class="row">${avatar(PEOPLE[0])}<span>A little note from Ani<br><small>Sample community</small></span></div><p>There’s room for you here.</p></div><button class="float-player" data-action="play" data-value="lagoon" aria-label="Play Sea glass, an original Sota Sessions instrumental"><span class="cover-thumb"></span><span><small>SOTA SESSIONS · ORIGINAL</small><strong>Sea glass</strong></span><span class="round-play">${icon('play')}</span></button></div></section><section class="welcome-band"><span class="serif">A place to belong.<br>A little more you.</span><div class="avatar-stack">${PEOPLE.slice(0,4).map(p=>avatar(p)).join('')}</div><p>Less noise. More of the people, conversations and moments you choose to keep close.</p></section><div class="section-title"><div><span class="eyebrow">Made for the things that matter</span><h2>Life happens between us.</h2></div></div><section class="feature-grid"><article class="feature-card sage">${icon('people')}<h2>Good people.<br>Close by.</h2><p>Find a familiar face, catch a little moment and make time for your people.</p><a class="text-link" href="#people">Meet the community ↗</a></article><article class="feature-card peach">${icon('chat')}<h2>Pull up<br>a seat.</h2><p>A good talanoa starts with hello. Bring your friends into a circle of your own.</p><a class="text-link" href="#talanoa">Explore the circles ↗</a></article><article class="feature-card lavender">${icon('music')}<h2>Find your<br>kind of sound.</h2><p>Original little instrumentals, community favourites and the music you bring.</p><a class="text-link" href="#music">Press play ↗</a></article></section><section class="welcome-end"><span class="eyebrow">Come exactly as you are</span><h2>Your little corner<br>of a bigger world.</h2><a class="btn primary" href="#space">Explore your space ${icon('arrow')}</a></section><footer class="footer"><span>Sota Kece · a little closer.<br>Original design, artwork and Sota Sessions.</span><button data-action="privacy" class="text-link">Your privacy</button></footer></main>`;}
function postCard(p){const who=p.person||person(p.author),own=p.author===me().id,open=state.comments.has(p.id),liked=likes().includes(p.id)||p.liked;return `<article class="card feed-post" data-post="${esc(p.id)}"><div class="row">${avatar(who)}<div class="grow"><button class="post-name" data-action="visit" data-value="${esc(who.handle||p.author)}">${esc(who.name)}</button><div class="post-meta">${timeAgo(p.createdAt)} · ${state.mode==='demo'?'Sample community':'Friends'}</div></div><button class="icon-btn ${saved().includes(p.id)?'on':''}" data-action="save-post" data-value="${esc(p.id)}" aria-label="${saved().includes(p.id)?'Unsave':'Save'} this moment" aria-pressed="${saved().includes(p.id)}">${icon('save')}</button></div><p class="post-body">${esc(p.text)}</p>${['craft','island','music'].includes(p.art)?art(p.art):''}<div class="post-actions"><button class="${liked?'on':''}" data-action="like" data-value="${esc(p.id)}" aria-pressed="${liked}" aria-label="${liked?'Liked':'Like'} this moment">${icon('heart')} ${p.likes+(likes().includes(p.id)?1:0)||'Like'}</button>${state.mode==='demo'?`<button data-action="comments" data-value="${esc(p.id)}" aria-expanded="${open}">${icon('chat')} ${p.comments?.length||'Reply'}</button>`:''}${own?`<span class="last stamp">Your moment</span>`:`<button class="last" data-action="visit" data-value="${esc(who.handle||p.author)}">Visit space ${icon('arrowUp')}</button>`}</div>${open?`<div class="comments">${(p.comments||[]).map(c=>`<div class="comment">${avatar(person(c.author))}<div><b>${esc(person(c.author).name)}</b><p>${esc(c.text)}</p></div></div>`).join('')}<form data-form="comment" data-id="${esc(p.id)}" class="comment-form"><label class="sr-only" for="comment-${esc(p.id)}">Write a reply</label><input id="comment-${esc(p.id)}" name="text" maxlength="300" placeholder="Leave a little reply…" required value="${esc(state.drafts['comment-'+p.id]||'')}" data-draft="comment-${esc(p.id)}"><button class="btn small" type="submit">Send</button></form></div>`:''}</article>`;}
function friendAside(){const friends=state.mode==='demo'?PEOPLE.filter(p=>state.demo.friends.includes(p.id)):(data().people||[]);return `<aside class="aside"><section class="card"><div class="row between"><h3>Your people</h3><a href="#people" class="stamp">See all ↗</a></div>${friends.slice(0,4).map(p=>`<button class="person" data-action="visit" data-value="${esc(p.handle)}">${avatar(p)}<span class="grow"><strong>${esc(p.name)}</strong><small>${state.mode==='demo'?esc(p.interest):'@'+esc(p.handle)}</small></span></button>`).join('')||'<p class="muted">Your people will appear here.</p>'}</section><section class="card soft"><span class="eyebrow">A little thought</span><p class="quote">“The best part of a place is who you share it with.”</p><span class="quote-credit">A note from Sota Kece</span></section><section class="card"><h3>Your circles</h3>${circles().filter(c=>c.joined).slice(0,3).map(c=>`<button class="mini-circle" data-action="open-circle" data-value="${esc(c.id)}"><span class="circle-icon ${esc(c.color)}">${esc(c.emoji)}</span><span><b>${esc(c.name)}</b><small>${c.members} ${c.members===1?'member':'members'}</small></span></button>`).join('')}<a href="#talanoa" class="text-link">Pull up a seat ↗</a></section><div class="aside-foot">Sota Kece · a little closer<br><button data-action="privacy">Your privacy</button> · <button data-action="about-demo">About this experience</button></div></aside>`;}
function home(){let feed=posts();if(state.feed==='saved')feed=feed.filter(p=>saved().includes(p.id));if(state.feed==='mine')feed=feed.filter(p=>p.author===me().id);return `${pageHeader('Your everyday, a little brighter','Bula, make yourself at home.')}<div class="columns"><div><section class="home-banner"><span class="eyebrow">There’s no place quite like your people</span><h2>Small moments.<br>Good company.</h2><p>A favourite song. A little hello. Something worth sharing.</p><span class="banner-art" aria-hidden="true"></span></section><div class="card composer" style="margin-top:20px">${avatar(me())}<button class="compose-prompt" data-action="compose">What’s a little good in your day?</button><button class="icon-btn" data-action="compose" aria-label="Share a moment">${icon('plus')}</button></div><div class="filter-row" role="group" aria-label="Filter moments">${[['all','Your people'],['mine','My moments'],['saved','Saved']].map(([value,label])=>`<button class="chip ${state.feed===value?'on':''}" data-action="feed-filter" data-value="${value}" aria-pressed="${state.feed===value}">${label}</button>`).join('')}</div><div class="stack">${feed.length?feed.map(postCard).join(''):empty('A little room for something good.',state.feed==='saved'?'Save a moment to keep it close.':'Share a moment, or find a friend to begin.',btn('Share a moment','compose','','primary'))}</div><div class="caught-up">${icon('sun')}You’re all caught up. Go make a little moment.</div></div>${friendAside()}</div>`;}
function peoplePage(){let list=state.mode==='demo'?PEOPLE:(state.query?state.searchResults:data().people||[]);if(state.mode==='demo'){if(state.people==='friends')list=list.filter(p=>state.demo.friends.includes(p.id));if(state.query)list=list.filter(p=>(p.name+' '+p.handle+' '+p.interest).toLowerCase().includes(state.query.toLowerCase()));}const pending=data().pending||[];return `${pageHeader('Good people. Real connection.','Your people, closer.','A familiar face makes the world feel smaller.')}<form class="search" data-form="people-search">${icon('search')}<label class="sr-only" for="people-query">${state.mode==='demo'?'Search people or interests':'Search by handle'}</label><input id="people-query" name="query" maxlength="80" value="${esc(state.query)}" placeholder="${state.mode==='demo'?'Search people, interests, a familiar name…':'Find someone by handle…'}"><button type="submit" class="btn small primary">Search</button></form>${pending.length?`<section class="card stack" style="margin-bottom:24px"><h3>Friend requests</h3>${pending.map(p=>`<div class="row">${avatar(memberProfile(p))}<span class="grow">${esc(p.display_name||p.handle)}</span>${btn('Accept','accept',p.friendship_id,'small')}</div>`).join('')}</section>`:''}<div class="filter-row">${[['all',state.mode==='demo'?'Explore people':'Your friends'],['friends','My people']].filter(x=>state.mode==='demo'||x[0]==='all').map(([v,l])=>`<button class="chip ${state.people===v?'on':''}" data-action="people-filter" data-value="${v}">${l}</button>`).join('')}<span class="stamp" style="margin-left:auto">${list.length} ${list.length===1?'person':'people'}</span></div><div class="people-grid">${list.map(p=>{const friend=state.mode==='demo'?state.demo.friends.includes(p.id):(data().people||[]).some(f=>f.id===p.id);const requested=(state.mode==='demo'?state.demo.requests:state.requests||[]).includes(p.id);return `<article class="card person-card"><div class="person-top ${esc(p.color)}"></div>${avatar(p)}<h3>${esc(p.name)}</h3><span class="handle">@${esc(p.handle)}</span>${p.interest?`<div><span class="tag">${esc(p.interest)}</span></div>`:''}<p>${esc(p.bio||'A little space of their own.')}</p><div class="card-bottom">${btn('Visit space','visit',p.handle,'small')}${friend?'<span class="tag">✓ Your people</span>':btn(requested?'Requested':'Connect','connect',p.id,'small primary')}</div></article>`;}).join('')}</div>${!list.length?empty('No familiar face just yet.','Try another name or handle. Your friends will appear here when they connect.'):''}`;}
function talanoa(){if(state.arg)return chatPage();return `${pageHeader('Make a little time together.','Pull up a seat.','The conversation feels better when everyone belongs.',btn(icon('plus')+' New circle','new-circle','','primary'))}<section class="talanoa-banner"><h2>Good conversations.<br>No need for an occasion.</h2>${icon('chat')}</section><div class="section-title"><div><span class="eyebrow">Your circles</span><h2>Who are we catching up with?</h2></div>${state.mode==='member'?btn('Join with a code','join-code','','small'):''}</div><div class="circles-grid">${circles().map(c=>`<article class="card circle-card"><span class="circle-icon ${esc(c.color)}">${esc(c.emoji)}</span><span class="eyebrow">${state.mode==='demo'?'Sample circle':'Private circle'}</span><h3 style="margin-top:8px">${esc(c.name)}</h3><p>${esc(c.description)}</p><div class="row between"><span class="stamp">${c.members} ${c.members===1?'member':'members'}</span>${btn(c.joined?'Open circle '+icon('arrow'):'Join circle',c.joined?'open-circle':'join-demo',c.id,c.joined?'small':'small primary')}</div></article>`).join('')}</div>${!circles().length?empty('Your first circle starts here.','Give it a name, bring your people, and make it yours.',btn('Start a circle','new-circle','','primary')):''}<p class="muted" style="font-size:11px;margin-top:24px">${state.mode==='demo'?'Sample conversations are fictional. Messages you write here stay on this device.':'Only members of your circle can read its messages. Invitations are shared by you.'}</p>`;}
function chatPage(){const c=circles().find(c=>c.id===state.arg);if(!c)return empty('That circle isn’t here.','Return to your circles to choose one.',`<a class="btn" href="#talanoa">All circles</a>`);if(!c.joined)return empty('There’s a seat for you.','Join this sample circle to try the conversation.',btn('Join circle','join-demo',c.id,'primary'));const messages=data().messages?.[c.id]||[];return `${pageHeader('A little time, together.',esc(c.name),'',`<a class="btn small" href="#talanoa">${icon('back')} All circles</a>`)}<div class="chat-layout"><aside class="chat-list"><h3>Your conversations</h3>${circles().filter(c=>c.joined).map(x=>`<button class="${x.id===c.id?'on':''}" data-action="open-circle" data-value="${esc(x.id)}"><span class="circle-icon ${esc(x.color)}">${esc(x.emoji)}</span><span><b>${esc(x.name)}</b><small>${x.members} ${x.members===1?'member':'members'}</small></span></button>`).join('')}</aside><section class="chat-main"><div class="chat-head row"><span class="circle-icon ${esc(c.color)}">${esc(c.emoji)}</span><div class="grow"><h2>${esc(c.name)}</h2><small>${c.members} ${c.members===1?'member':'members'} · ${state.mode==='demo'?'Sample conversation':'Private circle'}</small></div>${btn('Details','circle-info',c.id,'small flat')}${state.mode==='member'?btn('Refresh','reload','','small flat'):''}</div><div class="messages" role="log" aria-label="Circle messages" aria-live="polite">${messages.map(m=>{const mine=m.author===me().id,who=m.person||person(m.author);return `<div class="message ${mine?'mine':''}">${avatar(who)}<div><div class="bubble"><b>${mine?'You':esc(who.name)}</b>${esc(m.text)}</div><div class="meta">${timeAgo(m.createdAt)}${mine&&state.mode==='demo'?' · Saved on this device':''}</div></div></div>`;}).join('')||'<div class="caught-up">Every good talanoa starts with hello.</div>'}</div><form class="message-form" data-form="message" data-id="${esc(c.id)}"><label for="message-text" class="sr-only">Message to ${esc(c.name)}</label><textarea id="message-text" name="text" maxlength="1200" rows="1" placeholder="A little hello…" data-draft="message-${esc(c.id)}" required>${esc(state.drafts['message-'+c.id]||'')}</textarea><button type="submit" class="btn primary" aria-label="Send message">${icon('arrow')}</button></form><div class="chat-note">${state.mode==='demo'?'Sample mode · no message is sent to a real person.':'Your words stay within this circle. Use Refresh to check for new messages.'}</div></section></div>`;}
function allTracks(){return [...ORIGINALS,...state.community,...state.uploads];}
function musicPage(){let tracks=state.music==='original'?[...ORIGINALS]:state.music==='community'?state.community:state.music==='local'?state.uploads:allTracks().filter(t=>favorites().includes(t.id));if(state.musicQuery)tracks=tracks.filter(t=>(t.title+' '+t.artist).toLowerCase().includes(state.musicQuery.toLowerCase()));const selected=player.track||ORIGINALS[0];return `${pageHeader('A little soundtrack to your day.','Find your rhythm.','Press play. Stay a little longer.',btn(icon('plus')+' Your music','upload','','small'))}<section class="music-hero">${album(ORIGINALS[0])}<div><span class="eyebrow">Original instrumental sketches · 4 tracks</span><h2>Slow island hours.</h2><p>Four little compositions, made for this space. A pause in the middle of everything.</p>${btn(icon('play')+' Play the sessions','play','lagoon','primary')}</div></section><div class="music-body"><div><div class="filter-row">${[['original','Sota Sessions'],['community','Community mix'],['favorites','Favourites'],['local','Your music']].map(([v,l])=>`<button class="chip ${state.music===v?'on':''}" data-action="music-filter" data-value="${v}">${l}</button>`).join('')}</div><form class="search" data-form="music-search">${icon('search')}<input name="query" aria-label="Search music" placeholder="Find a song…" maxlength="100" value="${esc(state.musicQuery)}"><button type="submit" class="btn small">Find</button></form>${state.music==='community'&&state.communityState==='loading'?'<p class="loading">Opening the community mix…</p>':state.music==='community'&&state.communityState==='error'?`<div class="error">The community playlist couldn’t connect. ${btn('Try again','load-catalogue','','small')}</div>`:''}<div class="track-list">${tracks.map((t,i)=>`<div class="track-row ${player.track?.id===t.id?'on':''}" data-track="${esc(t.id)}"><span class="number">${String(i+1).padStart(2,'0')}</span><button class="track-pick" data-action="play" data-value="${esc(t.id)}" aria-label="Play ${esc(t.title)}">${album(t,true)}<span><strong>${esc(t.title)}</strong><small>${esc(t.artist)}</small></span></button><span class="duration">${t.duration?'0:'+String(t.duration).padStart(2,'0'):''}</span><button class="icon-btn favorite ${favorites().includes(t.id)?'on':''}" data-action="favorite" data-value="${esc(t.id)}" aria-label="${favorites().includes(t.id)?'Unfavourite':'Favourite'} ${esc(t.title)}" aria-pressed="${favorites().includes(t.id)}">${icon('heart')}</button></div>`).join('')}</div>${!tracks.length&&state.communityState!=='loading'?empty(state.music==='favorites'?'Keep a good song close.':state.music==='local'?'Bring your kind of sound.':'No songs found.',state.music==='local'?'Choose an audio file from your device. It plays here without uploading.':'Try another search or explore Sota Sessions.',state.music==='local'?btn('Choose a music file','upload','','primary'):''):''}<p class="muted" style="font-size:10px;margin-top:19px">${state.music==='original'?'Original synthesized instrumentals created for Sota Kece Revised. No recordings or samples.':state.music==='community'?'The existing shared community catalogue. Streaming uses your connection.':state.music==='local'?'Files stay on your device and are available in this tab until you close it.':'Your favourite tracks, kept together on this device.'}</p></div><aside class="stack"><section class="card now-card">${album(selected)}<span class="eyebrow">A little listening room</span><h3 style="margin-top:12px">${esc(selected.title)}</h3><p>${esc(selected.artist)}</p><div class="transport"><button class="icon-btn" data-action="previous" aria-label="Previous track">${icon('previous')}</button><button class="icon-btn main-play" data-action="toggle-play" aria-label="Play or pause music">${icon(audio.paused?'play':'pause')}</button><button class="icon-btn" data-action="next" aria-label="Next track">${icon('next')}</button></div></section><section class="card music-note">${icon('music')}<h3>Good music<br>goes with you.</h3><p>Your soundtrack keeps playing while you catch up, chat or make your space your own.</p></section></aside></div>`;}
function profilePage(){const visitor=state.visitor,own=!state.arg||state.arg===me().handle||state.arg===me().id,p=own?me():visitor||person(state.arg),friends=state.mode==='demo'?PEOPLE.filter(x=>state.demo.friends.includes(x.id)):data().people||[],mine=posts().filter(x=>x.author===p.id);if(!own&&!visitor)return empty('This space is private.','Connect as friends to see more.');if(visitor?.closed)return empty(p.name+'’s space is private.','Only their friends can see this space.',btn('Ask to connect','connect',p.id,'primary'));return `${!own?`<div class="visitor-note"><a href="#people">← Back to your people</a> · ${state.mode==='demo'?'A fictional sample profile':'A friend’s space'}</div>`:''}<section class="card profile-hero"><div class="profile-cover ${esc(p.theme||'lagoon')}"><span class="profile-caption">A little more ${own?'you':'them'}.</span></div><div class="profile-main"><div class="row">${avatar(p,'large')}<div class="grow"></div>${own?btn(icon('settings')+' Edit my space','edit-profile','','small'):btn('Find a circle','browse-circles','','small primary')}</div><span class="eyebrow" style="margin-top:17px">${own?'This is your little corner':'A little corner of their world'}</span><h1 tabindex="-1" id="page-title">${esc(p.name)}</h1><span class="muted" style="font-size:12px">@${esc(p.handle)}</span><p class="bio">${esc(p.bio||'Good people. Small moments. A place to be yourself.')}</p><div class="profile-stats"><span><b>${own?friends.length:state.mode==='demo'?3:'—'}</b> people</span><span><b>${mine.length}</b> moments</span><span>${state.mode==='demo'?'Sample space':'Your own pace'}</span></div></div></section><div class="profile-content"><div class="stack"><section class="card"><h3>${own?'My people':'Your people'}</h3><div class="mate-grid">${friends.slice(0,6).map(x=>`<button data-action="visit" data-value="${esc(x.handle)}">${avatar(x)}${esc(x.name.split(' ')[0])}</button>`).join('')||'<p class="muted">Your friends will appear here.</p>'}</div></section><section class="card"><span class="eyebrow">The soundtrack</span><button class="profile-song" data-action="play" data-value="lagoon">${album(ORIGINALS[0],true)}<span><strong>Sea glass</strong><br><small>Sota Sessions · press play</small></span></button></section><section class="card soft profile-note-card"><p class="profile-note">A space doesn’t have to be big to feel like home.</p></section></div><div><div class="section-title"><h2>${own?'My little moments':'Little moments'}</h2>${own?btn(icon('plus')+' Share','compose','','small'):''}</div><div class="stack">${mine.length?mine.map(postCard).join(''):empty(own?'Start with a little hello.':'A little space to grow.',own?'Share something from your day and make this space feel like you.':'Their moments will appear here.',own?btn('Share my first moment','compose','','primary'):'')}</div></div></div>`;}
function settingsPage(){return `${pageHeader('A space that works for you.','Make yourself comfortable.')}<div class="settings-grid"><section class="card"><h2>Your space</h2><p>A name, a little story and a colour that feels like you. You can change your mind any time.</p>${btn('Edit my space','edit-profile','','primary')}</section><section class="card"><h2>Your privacy</h2><p>${state.mode==='demo'?'This sample community lives on this device. Its people and conversations are fictional. Nothing you post here is sent to another person.':'Your account uses the existing Sota Kece service. Your real community data is fetched only after sign-in and is not saved into the sample community.'}</p>${btn('Read the details','privacy','','small')}</section><section class="card"><h2>${state.mode==='demo'?'Keep your sample work':'Your account'}</h2><p>${state.mode==='demo'?'Download your sample profile, moments and conversations as a JSON file. Your music files are never included.':'Sign out on a shared device. This clears the member pages and any unsent drafts from this tab.'}</p>${state.mode==='demo'?btn(icon('download')+' Download sample data','export-demo','','small'):btn('Sign out','signout','','small')}</section><section class="card"><h2>${state.mode==='demo'?'Ready for your real people?':'A little breathing room'}</h2><p>${state.mode==='demo'?'Sign in to your existing account, or create your own space. Sample activity stays separate from your account.':'Keep only the sound you choose. Music starts only when you press play.'}</p>${state.mode==='demo'?btn('Sign in to my account','auth','','primary'):btn('Pause music','pause','','small')}<div style="margin-top:17px"><a class="text-link" href="#welcome">Back to the welcome page</a></div></section></div>`;}
function render(){const theme=THEMES[me().theme]||THEMES.lagoon;document.documentElement.style.setProperty('--accent',theme.color);document.documentElement.style.setProperty('--paper',theme.paper);document.body.classList.toggle('welcome-mode',state.page==='welcome');let content;if(state.loading)content=pageHeader('A little closer.','Opening your space.')+'<div class="loading"><div class="spinner"></div>Bringing your people together…</div>';else if(state.error)content=empty('A little interruption.',state.error,btn('Try again','reload','','primary'));else content=({home,people:peoplePage,talanoa,music:musicPage,space:profilePage,settings:settingsPage}[state.page]||home)();app.innerHTML=state.page==='welcome'?welcome():shell(content);document.title=(state.page==='welcome'?'Sota Kece — a little closer':(navItems.find(x=>x[0]===state.page)?.[1]||'Settings')+' · Sota Kece');syncAudio();}
async function loadPage(focus=false){const route=parseRoute(location.hash);Object.assign(state,route);state.error='';state.visitor=null;const run=++state.epoch;state.loading=false;if(state.mode==='demo'){if(state.page==='space'&&state.arg)state.visitor=PEOPLE.find(p=>p.handle===state.arg||p.id===state.arg)||null;render();afterNavigation(focus);return;}if(state.page==='welcome'){render();afterNavigation(focus);return;}state.loading=true;render();try{if(!state.member?.me){const own=await state.service.me();if(run!==state.epoch)return;if(!own){state.loading=false;render();if(!state.recovery)setupDialog();return;}try{const theme=sessionStorage.getItem('sota-revised-theme-'+own.id);if(THEMES[theme])own.theme=theme;}catch{}state.member.me=own;}const s=state.service;
 if(state.page==='home'){const [feed,people,groups]=await Promise.all([s.feed(),s.friends(),s.circles()]);if(run!==state.epoch)return;Object.assign(state.member,{posts:feed,people,circles:groups});state.liked=[];}
 if(state.page==='people'){const [people,pending]=await Promise.all([s.friends(),s.pending()]);if(run!==state.epoch)return;Object.assign(state.member,{people,pending});}
 if(state.page==='talanoa'){const groups=await s.circles();if(run!==state.epoch)return;state.member.circles=groups;if(state.arg){const messages=await s.messages(state.arg);if(run!==state.epoch)return;state.member.messages[state.arg]=messages;}}
 if(state.page==='space'){const [feed,people]=await Promise.all([s.feed(),s.friends()]);if(run!==state.epoch)return;Object.assign(state.member,{posts:feed,people});state.liked=[];if(state.arg&&state.arg!==me().handle){const room=await s.room(state.arg);if(run!==state.epoch)return;state.visitor=room?.found?{...memberProfile(room.profile),closed:!room.visible}:null;}}
 }catch(error){if(run===state.epoch)state.error=error.message;}finally{if(run===state.epoch){state.loading=false;render();afterNavigation(focus);}}}
function afterNavigation(focus){if(focus){document.querySelector('#page-title')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}const messages=document.querySelector('.messages');if(messages)messages.scrollTop=messages.scrollHeight;}
function showDialog(title,content,kicker='A little more you'){dialog.innerHTML=`<header class="dialog-head"><div><span class="eyebrow">${kicker}</span><h2 id="dialog-title">${title}</h2></div><button class="icon-btn" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></header>${content}`;if(!dialog.open)dialog.showModal();dialog.querySelector('input:not([type=radio]),textarea,select')?.focus();}
function composeDialog(){showDialog('Share a little moment.',`<form class="form-stack" data-form="post"><div class="row">${avatar(me())}<span><b>${esc(me().name)}</b><br><small>${state.mode==='demo'?'Sample community · on this device':'Shared with your friends'}</small></span></div><label class="sr-only" for="post-text">Your moment</label><textarea id="post-text" name="text" maxlength="500" placeholder="Something good, something small, something you…" data-draft="post" required>${esc(state.drafts.post||'')}</textarea>${state.mode==='demo'?`<div><span class="eyebrow" style="margin-bottom:10px">Add a little artwork</span><div class="art-options">${[['','Just words'],['island','Island hours'],['craft','Made by hand'],['music','On repeat']].map(([v,l])=>`<label class="art-option"><input type="radio" name="art" value="${v}" ${v===(state.drafts.postArt||'')?'checked':''}> ${l}</label>`).join('')}</div></div>`:''}<div class="form-error" role="alert"></div><div class="form-foot"><span class="char-count">500 characters · ${state.mode==='demo'?'local sample':'your people'}</span><button class="btn primary" type="submit">Share moment ${icon('arrow')}</button></div></form>`);}
function editProfileDialog(){const p=me();showDialog('Make it feel like you.',`<form class="form-stack" data-form="profile"><div class="form-grid"><label>Your name<input name="name" value="${esc(p.name)}" required maxlength="40"></label><label>A little symbol<input name="emoji" value="${esc(p.emoji)}" maxlength="8" aria-label="Profile emoji"></label></div><label>A little about you<textarea name="bio" maxlength="400" rows="3">${esc(p.bio)}</textarea></label><div><span class="eyebrow" style="margin-bottom:13px">${state.mode==='demo'?'Your space, your colour':'Theme on this device'}</span><div class="theme-grid">${Object.entries(THEMES).map(([k,t])=>`<label class="theme-pick"><input type="radio" name="theme" value="${k}" ${p.theme===k?'checked':''}><span style="--swatch:${t.color}"></span>${t.name}</label>`).join('')}</div></div><div class="form-error" role="alert"></div><div class="form-foot"><small>${state.mode==='demo'?'Saved to your sample space.':'Name and bio update your real profile.'}</small><button class="btn primary" type="submit">Save my space</button></div></form>`);}
function authDialog(signup=false){showDialog(signup?'Your people are waiting.':'Welcome back.',`<p class="dialog-copy">${signup?'Create your own space. Sample activity stays separate.':'Sign in to your existing Sota Kece account. Your sample activity stays on this device.'}</p><form class="form-stack" data-form="${signup?'signup':'signin'}">${signup?'<div class="form-grid"><label>Your name<input name="name" autocomplete="name" required maxlength="40"></label><label>Your handle<input name="handle" required pattern="[a-z0-9_]{3,20}" title="3–20 lowercase letters, numbers or underscores" maxlength="20" autocapitalize="none"></label></div>':''}<label>Email<input name="email" type="email" autocomplete="email" required maxlength="254"></label><label>Password<input name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="${signup?8:1}" required></label>${signup?'<label>Age group<select name="ageBand" required><option value="">Choose your age group</option><option value="teen">16–17</option><option value="adult">18 or over</option></select><small>Sota Kece is for people aged 16 and over. Only your age group is saved.</small></label>':''}<div class="form-error" role="alert"></div><button type="submit" class="btn primary wide">${signup?'Create my account':'Sign in'} ${icon('arrow')}</button>${!signup?'<button type="button" class="text-link" data-action="forgot-password">Forgot your password?</button>':''}<button type="button" class="btn flat" data-action="${signup?'auth':'auth-up'}">${signup?'Already have an account? Sign in':'New here? Create your space'}</button></form>`,'A little closer to home');}
function setupDialog(){showDialog('Finish making your space.',`<p class="dialog-copy">You’re signed in. Choose the name and handle your people will see.</p><form class="form-stack" data-form="setup"><label>Your name<input name="name" required maxlength="40"></label><label>Your handle<input name="handle" pattern="[a-z0-9_]{3,20}" required maxlength="20" autocapitalize="none"></label><label>Age group<select name="ageBand" required><option value="">Choose your age group</option><option value="teen">16–17</option><option value="adult">18 or over</option></select></label><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Make my space</button></form>`);}

// Playback lives outside the changing pages, so navigation never restarts a song.
let player;
player=new Player(audio,syncAudio);
const clock=value=>Number.isFinite(value)?Math.floor(value/60)+':'+String(Math.floor(value%60)).padStart(2,'0'):'0:00';
function syncAudio(){if(!player)return;const box=document.querySelector('#player'),track=player.track;box.hidden=!track;if(!track)return;box.className='player';if(box.dataset.track!==track.id){box.dataset.track=track.id;box.innerHTML=`<div class="player-song">${album(track,true)}<span><strong>${esc(track.title)}</strong><small>${esc(track.artist)}</small></span></div><div class="player-middle"><div class="transport"><button class="icon-btn" data-action="previous" aria-label="Previous track">${icon('previous')}</button><button class="icon-btn main-play" data-action="toggle-play" aria-label="Pause music">${icon('pause')}</button><button class="icon-btn" data-action="next" aria-label="Next track">${icon('next')}</button></div><div class="seek-row"><span data-time>0:00</span><input type="range" min="0" max="24" step="0.1" value="0" data-seek aria-label="Playback position"><span data-duration>0:24</span></div></div><div class="player-extra"><button class="icon-btn" data-action="repeat" aria-label="Repeat track" aria-pressed="false">${icon('repeat')}</button>${icon('volume')}<input type="range" min="0" max="1" step="0.01" value="${audio.volume}" data-volume aria-label="Volume"></div><span class="player-error" role="status"></span>`;}
 document.querySelectorAll('[data-action="toggle-play"]').forEach(b=>{b.innerHTML=icon(audio.paused?'play':'pause');b.setAttribute('aria-label',audio.paused?'Play music':'Pause music');});
 document.querySelectorAll('[data-action="repeat"]').forEach(b=>{b.classList.toggle('on',player.repeat);b.setAttribute('aria-pressed',String(player.repeat));});
 document.querySelectorAll('[data-track]').forEach(row=>{if(row!==box)row.classList.toggle('on',row.dataset.track===track.id);});
 const duration=Number.isFinite(audio.duration)?audio.duration:track.duration||0;
 box.querySelector('[data-time]').textContent=clock(audio.currentTime);box.querySelector('[data-duration]').textContent=clock(duration);
 const seek=box.querySelector('[data-seek]');seek.max=duration;if(document.activeElement!==seek)seek.value=audio.currentTime||0;
 box.querySelector('.player-error').textContent=player.error;
 const now=document.querySelector('.now-card');if(now){now.querySelector('h3').textContent=track.title;now.querySelector('p').textContent=track.artist;now.querySelector('.album-art').className='album-art '+track.art;}
}
function circleDialog(){showDialog('Make a little circle.',`<form class="form-stack" data-form="circle"><label>Circle name<input name="name" maxlength="40" required placeholder="The Sunday people"></label>${state.mode==='demo'?'<label>A little about this circle<textarea name="description" maxlength="180" placeholder="A place for…"></textarea></label>':''}<p class="dialog-copy">${state.mode==='demo'?'This creates a local sample conversation. No invitations are sent.':'This creates a private circle. Share its invitation code with the people you choose.'}</p><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Create circle</button></form>`);}
function privacyDialog(){showDialog('Your space. Your choice.',`<div class="privacy-copy"><h3>In the sample community</h3><p>The people and conversations are fictional. Your sample profile, moments, favourites and messages are saved in this browser. Nothing is sent to real members. Clear this site’s browser data to remove them.</p><h3>When you sign in</h3><p>Your existing Sota Kece account and its access rules are used. Sharing a moment, connecting or sending a message updates that account. Member content stays separate from sample storage. Sign out on a shared device.</p><h3>Your music</h3><p>Sota Sessions is generated in your browser. Files you choose stay on your device. Community tracks stream from the shared catalogue. Fonts and sign-in load from external services.</p></div>`,'A little clarity');}
async function catalogue(){if(state.communityState==='loading')return;state.communityState='loading';render();try{const response=await fetch('https://fijihistory.com/shared-music/catalogue.json',{signal:AbortSignal.timeout(10000)});if(!response.ok)throw Error('Playlist unavailable');state.community=validateCatalogue(await response.json());state.communityState='ready';}catch{state.communityState='error';}if(state.page==='music')render();}
function upload(){const input=document.createElement('input');input.type='file';input.accept='audio/*';input.multiple=true;input.addEventListener('change',()=>{let skipped=0;for(const file of input.files){if(state.uploads.length>=12||file.size>50*1024*1024||(!file.type.startsWith('audio/')&&!/\.(mp3|wav|ogg|m4a|aac|flac)$/i.test(file.name))){skipped++;continue;}state.uploads.push({id:'local-'+crypto.randomUUID(),title:file.name.replace(/\.[^.]+$/,''),artist:'From your device · never uploaded',art:'night',url:URL.createObjectURL(file),kind:'local'});}state.music='local';state.musicQuery='';if(state.page!=='music')go('music');else render();if(skipped)toast('Some files were skipped. Choose up to 12 audio files, each under 50 MB.');});input.click();}
function clearMember(){state.epoch++;state.service?.owner(null);state.mode='demo';state.member=null;state.drafts={};state.comments.clear();state.searchResults=[];state.query='';state.visitor=null;state.saved=[];state.liked=[];state.favorites=[];state.feed='all';state.error='';state.loading=false;state.requests=[];state.recovery=false;dialog.close();}
function setMember(session){if(!session?.user){if(state.mode==='member'){clearMember();loadPage();}return;}if(state.mode==='member'&&state.service?.user?.id===session.user.id)return;clearMember();state.service.owner(session.user);state.mode='member';state.member={me:null,posts:[],people:[],pending:[],circles:[],messages:{}};if(state.page==='welcome')go('home');else loadPage();}
let authReady,authEvent=0;
async function ensureAuth(){if(!authReady)authReady=(async()=>{state.sb=await client();state.service=new Service(state.sb);state.sb.auth.onAuthStateChange((_event,session)=>{const event=++authEvent;if(state.mode==='member'&&state.service.user?.id!==session?.user?.id){clearMember();render();}setTimeout(()=>{if(event===authEvent){setMember(session);if(_event==='PASSWORD_RECOVERY'){state.recovery=true;recoveryDialog();}}},0);});return state.sb;})().catch(()=>{authReady=null;throw Error('Sign-in could not connect. Check your connection and try again.');});return authReady;}
async function signout(){const {error}=await state.sb.auth.signOut();if(error)throw Error(error.message);clearMember();go('welcome');toast('Signed out. Your member pages have been cleared.');}
async function action(name,value,button){
 switch(name){
 case 'auth':authDialog();ensureAuth().catch(error=>toast(error.message));break;case 'auth-up':authDialog(true);ensureAuth().catch(error=>toast(error.message));break;case 'close-dialog':dialog.close();break;
 case 'compose':composeDialog();break;case 'edit-profile':editProfileDialog();break;case 'reload':await loadPage();break;
 case 'feed-filter':state.feed=value;render();break;case 'people-filter':state.people=value;render();break;
 case 'visit':go('space',value===me().handle||value===me().id?'':value);break;
 case 'comments':state.comments.has(value)?state.comments.delete(value):state.comments.add(value);render();break;
 case 'save-post':toggle(saved(),value);persist();render();break;
 case 'like':if(state.mode==='demo'){toggle(likes(),value);persist();render();}else if(!likes().includes(value)&&!posts().find(p=>p.id===value)?.liked){await state.service.like(value);state.liked.push(value);render();}break;
 case 'connect':if(state.mode==='demo'){if(!state.demo.requests.includes(value)){state.demo.requests.push(value);persist();render();}toast('Sample request saved. No real person was contacted.');}else{if(state.requests?.includes(value))break;await state.service.request(value);(state.requests??=[]).push(value);render();toast('Friend request sent.');}break;
 case 'accept':await state.service.accept(value);await loadPage();toast('Added to your people.');break;
 case 'browse-circles':go('talanoa');break;case 'open-circle':go('talanoa',value);break;
 case 'join-demo':{const c=state.demo.circles.find(c=>c.id===value);if(c&&!c.joined){c.joined=true;c.members++;persist();}go('talanoa',value);break;}
 case 'new-circle':circleDialog();break;
 case 'join-code':showDialog('There’s a seat for you.',`<form class="form-stack" data-form="join"><label>Invitation code<input name="code" required maxlength="100" autocomplete="off"></label><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Join circle</button></form>`);break;
 case 'circle-info':{const c=circles().find(c=>c.id===value);showDialog(esc(c?.name||'Your circle'),`<p class="dialog-copy">${esc(c?.description||'A private conversation for your people.')}</p>${state.mode==='demo'?'<p>This is a fictional sample circle. Messages stay on this device. Sample members do not send automatic replies.</p>':c?.join_code?`<p>Share this invitation code yourself with someone you want to invite:</p><p class="invite-code">${esc(c.join_code)}</p>`:'<p>Your circle is private. Refresh the conversation to check for new messages.</p>'}`);break;}
 case 'play':{const track=allTracks().find(t=>t.id===value);if(track){player.queue=track.kind==='local'?state.uploads:track.kind==='community'?state.community:[...ORIGINALS];await player.play(track);}break;}
 case 'toggle-play':player.toggle();break;case 'next':player.next(1);break;case 'previous':player.next(-1);break;case 'pause':player.stop();break;
 case 'repeat':player.repeat=!player.repeat;syncAudio();break;
 case 'favorite':toggle(favorites(),value);persist();render();break;
 case 'music-filter':state.music=value;state.musicQuery='';render();if((value==='community'||value==='favorites'&&favorites().some(id=>id.startsWith('community-')))&&state.communityState==='idle')await catalogue();break;
 case 'load-catalogue':await catalogue();break;case 'upload':upload();break;
 case 'forgot-password':showDialog('Find your way back.',`<form class="form-stack" data-form="reset-email"><p class="dialog-copy">We’ll email a secure link to reset your password.</p><label>Email<input name="email" type="email" autocomplete="email" required></label><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Send reset link</button></form>`);break;case 'privacy':privacyDialog();break;
 case 'about-demo':showDialog('A space to try everything.',`<p class="dialog-copy">This is a working preview with fictional people and conversations. Share a moment, join a circle, play a song and make My space your own.</p><p>Your sample changes stay in this browser. Signing in opens your real account, with no sample content copied across.</p>${btn('Make my sample space','edit-profile','','primary')}`,'Welcome to the sample community');break;
 case 'activity':{const pending=state.mode==='demo'?state.demo.requests.length:data().pending?.length||0;showDialog('A little catch-up.',`<p class="dialog-copy">${state.mode==='demo'?`${pending} sample connection ${pending===1?'request':'requests'} saved. Sample people do not reply automatically.`:pending?`${pending} friend ${pending===1?'request is':'requests are'} waiting in People.`:'Open People to check friend requests, or refresh your circles for new messages.'}</p><a class="btn primary" href="#people" data-action="close-dialog">Go to People</a>`);break;}
 case 'signout':await signout();break;
 case 'export-demo':{const url=URL.createObjectURL(new Blob([JSON.stringify(state.demo,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='sota-kece-sample.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sample data prepared for download.');break;}
 default:throw Error('That action is not available.');
 }
}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;const {action:name,value=''}=button.dataset,key=name+':'+value;if(state.busy.has(key))return;state.busy.add(key);button.disabled=true;try{await action(name,value,button);}catch(error){toast(error.message||'That did not save. Please try again.');}finally{state.busy.delete(key);button.disabled=false;}});
document.addEventListener('input',event=>{const input=event.target;if(input.dataset.draft)state.drafts[input.dataset.draft]=input.value;if(input.hasAttribute('data-seek'))player.seek(input.value);if(input.hasAttribute('data-volume'))player.setVolume(input.value);});
document.addEventListener('change',event=>{if(event.target.name==='art')state.drafts.postArt=event.target.value;});
dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});
document.addEventListener('submit',async event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();if(!form.reportValidity())return;const kind=form.dataset.form,key='form:'+kind;if(state.busy.has(key))return;state.busy.add(key);const submit=form.querySelector('[type="submit"]'),values=Object.fromEntries(new FormData(form)),owner=state.service?.user?.id,mode=state.mode;let errorLine=form.querySelector('.form-error');if(errorLine)errorLine.textContent='';if(submit)submit.disabled=true;
 const current=()=>{if(mode!==state.mode||owner!==state.service?.user?.id)throw Error('Your account changed. Please try again.');};
 try{
 if(kind==='post'){const text=cleanText(values.text);if(mode==='demo'){addPost(state.demo,text,values.art);persist();}else await state.service.post(text);current();delete state.drafts.post;delete state.drafts.postArt;dialog.close();state.feed='all';if(state.page==='home')await loadPage();else go('home');toast(mode==='demo'?'Your moment is saved in the sample community.':'Your moment is shared.');}
 else if(kind==='comment'){addComment(state.demo,form.dataset.id,values.text);delete state.drafts['comment-'+form.dataset.id];persist();render();}
 else if(kind==='message'){const text=cleanText(values.text,1200),circle=form.dataset.id;if(mode==='demo'){addMessage(state.demo,circle,text);persist();}else await state.service.send(circle,text);current();delete state.drafts['message-'+circle];if(mode==='member'){const messages=await state.service.messages(circle);current();state.member.messages[circle]=messages;}render();afterNavigation(false);document.querySelector('#message-text')?.focus();}
 else if(kind==='profile'){const next=updateProfile({profile:clone(me())},values);if(mode==='demo'){state.demo.profile=next;persist();}else{await state.service.saveProfile(next);current();state.member.me=next;try{sessionStorage.setItem('sota-revised-theme-'+owner,next.theme);}catch{}}dialog.close();render();toast('Your space feels a little more you.');}
 else if(kind==='circle'){const name=cleanText(values.name,40);let circle;if(mode==='demo'){circle=newCircle(state.demo,name,values.description);persist();}else{const result=await state.service.createCircle(name);current();circle=Array.isArray(result)?result[0]:result;state.member.circles=await state.service.circles();current();}dialog.close();go('talanoa',String(circle?.id||circle?.crew_id||''));toast('Your circle is ready.');}
 else if(kind==='join'){const joined=await state.service.joinCircle(cleanText(values.code,100));current();if(joined?.error)throw Error(joined.error);if(joined===false||joined?.ok===false)throw Error('That invitation code could not be used. Check it and try again.');dialog.close();go('talanoa');await loadPage();toast('You joined the circle.');}
 else if(kind==='people-search'){state.query=values.query.trim();if(mode==='member'&&state.query){const query=state.query,found=await state.service.search(query);current();if(query!==state.query)return;state.searchResults=found;}render();document.querySelector('#people-query')?.focus();}
 else if(kind==='music-search'){state.musicQuery=values.query.trim();render();document.querySelector('[aria-label="Search music"]')?.focus();}
 else if(kind==='reset-email'){const sb=await ensureAuth();const {error}=await sb.auth.resetPasswordForEmail(values.email.trim(),{redirectTo:location.origin+'/revised/'});if(error)throw Error(error.message);showDialog('Check your inbox.',`<p class="dialog-copy">If an account uses that address, a password reset link will arrive. Follow the link to choose your new password.</p>`);}
 else if(kind==='new-password'){if(values.password!==values.confirm)throw Error('The passwords do not match.');const {error}=await state.sb.auth.updateUser({password:values.password});if(error)throw Error(error.message);state.recovery=false;dialog.close();go('home');toast('Your password has been updated.');}
 else if(kind==='signin'||kind==='signup'){const sb=await ensureAuth();let response;if(kind==='signin')response=await sb.auth.signInWithPassword({email:values.email.trim(),password:values.password});else response=await sb.auth.signUp({email:values.email.trim(),password:values.password,options:{data:{display_name:cleanText(values.name,40),requested_handle:values.handle,age_band:values.ageBand},emailRedirectTo:location.origin+'/revised/'}});if(response.error)throw Error(response.error.message);form.querySelector('[name="password"]').value='';if(response.data.session){setMember(response.data.session);dialog.close();go('home');}else showDialog('Check your inbox.',`<p class="dialog-copy">If this address can be registered, a confirmation email will arrive. Follow its link, then sign in here to finish your space.</p>${btn('Back to sign in','auth','','primary')}`);}
 else if(kind==='setup'){if(!/^[a-z0-9_]{3,20}$/.test(values.handle)||!['teen','adult'].includes(values.ageBand))throw Error('Choose a valid handle and age group.');await state.service.setup({...values,name:cleanText(values.name,40)});current();state.member.me=await state.service.me();current();dialog.close();go('home');await loadPage();}
 }catch(error){if(!form.isConnected)toast(error.message);else{if(!errorLine){errorLine=document.createElement('div');errorLine.className='form-error';errorLine.setAttribute('role','alert');form.append(errorLine);}errorLine.textContent=error.message||'That did not save. Please try again.';}}
 finally{state.busy.delete(key);if(submit)submit.disabled=false;}
});
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){document.querySelector('main')?.focus();return;}loadPage(true);});
window.addEventListener('offline',()=>toast('You’re offline. The sample space still works while this tab is open.'));
window.addEventListener('pagehide',event=>{if(!event.persisted){player.destroy();state.uploads.forEach(t=>URL.revokeObjectURL(t.url));}});
loadPage();
if(storage.getItem('sota-revised-auth')||/(?:access_token|code)=/.test(location.hash+location.search))ensureAuth().then(sb=>sb.auth.getSession()).then(({data,error})=>{if(error)throw error;setMember(data.session);}).catch(()=>toast('Your account could not reconnect. You can try signing in again.'));

function recoveryDialog(){showDialog('A fresh start.',`<form class="form-stack" data-form="new-password"><label>New password<input name="password" type="password" minlength="8" autocomplete="new-password" required></label><label>Confirm new password<input name="confirm" type="password" minlength="8" autocomplete="new-password" required></label><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Save new password</button></form>`);}
